const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '入射光线' },
      { kind: 'text', payload: '法线' },
      { kind: 'text', payload: '反射光线' },
      { kind: 'text', payload: '反射角' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var O = { x: W * 0.50, y: H * 0.72 };
    var mirrorY = O.y;
    var normalTop = H * 0.16;
    var incStart = { x: W * 0.18, y: H * 0.18 };
    var refEnd = { x: W * 0.82, y: H * 0.18 };
    var fs = Math.max(12, Math.round(Math.min(W, H) * 0.035));
    var stroke = '#26354a';
    var lineWidth = Math.max(1.5, Math.min(W, H) * 0.004);
    var arrowSize = Math.max(8, Math.min(W, H) * 0.035);
    function line(x1, y1, x2, y2) {
      return visualSdk.polyline([[x1, y1], [x2, y2]]);
    }
    function dashed(x1, y1, x2, y2, dash, gap) {
      var dx = x2 - x1, dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len === 0) return [];
      var ux = dx / len, uy = dy / len;
      var cmds = [];
      var d = 0;
      while (d < len) {
        var d2 = Math.min(d + dash, len);
        cmds = cmds.concat(visualSdk.polyline([[x1 + ux * d, y1 + uy * d], [x1 + ux * d2, y1 + uy * d2]]));
        d += dash + gap;
      }
      return cmds;
    }
    function arrow(x1, y1, x2, y2, size) {
      var a = Math.atan2(y2 - y1, x2 - x1);
      var backX = x2 - Math.cos(a) * size;
      var backY = y2 - Math.sin(a) * size;
      var w = size * 0.45;
      var p1x = backX + Math.cos(a + Math.PI / 2) * w;
      var p1y = backY + Math.sin(a + Math.PI / 2) * w;
      var p2x = backX + Math.cos(a - Math.PI / 2) * w;
      var p2y = backY + Math.sin(a - Math.PI / 2) * w;
      return visualSdk.polyline([[x1, y1], [x2, y2]])
        .concat(visualSdk.polyline([[x2, y2], [p1x, p1y]]))
        .concat(visualSdk.polyline([[x2, y2], [p2x, p2y]]));
    }
    function arc(cx, cy, r, a0, a1, steps) {
      var pts = [];
      for (var i = 0; i <= steps; i++) {
        var t = a0 + (a1 - a0) * i / steps;
        pts.push([cx + Math.cos(t) * r, cy + Math.sin(t) * r]);
      }
      return visualSdk.polyline(pts);
    }
    var normalCmds = dashed(O.x, O.y, O.x, normalTop, Math.max(5, H * 0.018), Math.max(4, H * 0.012));
    var incCmds = arrow(incStart.x, incStart.y, O.x, O.y, arrowSize);
    var refCmds = arrow(O.x, O.y, refEnd.x, refEnd.y, arrowSize);
    var refAngle = Math.atan2(refEnd.y - O.y, refEnd.x - O.x);
    var arcR = Math.min(W, H) * 0.13;
    var arcCmds = arc(O.x, O.y, arcR, -Math.PI / 2, refAngle, 24);
    var midAngle = (-Math.PI / 2 + refAngle) / 2;
    var angleLabelX = O.x + Math.cos(midAngle) * arcR * 1.9;
    var angleLabelY = O.y + Math.sin(midAngle) * arcR * 1.9;
    var incMid = { x: (incStart.x + O.x) / 2, y: (incStart.y + O.y) / 2 };
    var refMid = { x: (O.x + refEnd.x) / 2, y: (O.y + refEnd.y) / 2 };
    return {
      schemaVersion: 1,
      sceneId: 'reflection-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'mirror', commands: line(W * 0.08, mirrorY, W * 0.92, mirrorY) },
        { id: 'normal', commands: normalCmds },
        { id: 'incident', commands: incCmds },
        { id: 'reflected', commands: refCmds },
        { id: 'angleArc', commands: arcCmds }
      ],
      root: { type: 'group', children: [
        { type: 'path', pathId: 'mirror', stroke: stroke, strokeWidth: lineWidth, fill: 'none' },
        { type: 'path', pathId: 'normal', stroke: stroke, strokeWidth: Math.max(1, lineWidth * 0.8), fill: 'none' },
        { type: 'path', pathId: 'incident', stroke: stroke, strokeWidth: lineWidth, fill: 'none' },
        { type: 'path', pathId: 'reflected', stroke: stroke, strokeWidth: lineWidth, fill: 'none' },
        { type: 'path', pathId: 'angleArc', stroke: stroke, strokeWidth: Math.max(1, lineWidth * 0.8), fill: 'none' },
        { type: 'label', text: '入射光线', x: incMid.x - fs * 0.8, y: incMid.y - fs * 0.2, fontSize: fs, fill: stroke, textAnchor: 'end' },
        { type: 'label', text: '法线', x: O.x + fs * 0.8, y: normalTop + fs * 0.9, fontSize: fs, fill: stroke, textAnchor: 'start' },
        { type: 'label', text: '反射光线', x: refMid.x + fs * 0.8, y: refMid.y - fs * 0.2, fontSize: fs, fill: stroke, textAnchor: 'start' },
        { type: 'label', text: '反射角', x: angleLabelX, y: angleLabelY, fontSize: fs, fill: stroke, textAnchor: 'start' }
      ] }
    };
  }
};
